python3 - <<'PY'
import json
x=json.load(open('/tmp/linear-schema.json'))
for typ,v in x.get('data',{}).get('__schema',{}).items():
 for f in v['fields']:
  if 'attachment' in f['name'].lower(): print(typ,f)
print(x.get('errors',''))
PY

